-- Form I bāb re-read from a 600-char window of Lane's own text: the
-- first pass truncated at 110 chars, and Lane's sigla list ((S, M, Msb, K,))
-- routinely pushes `aor.` past that. Only generated families are touched.

UPDATE ar_ling_lexicon_block SET data_json = (  SELECT json_set(json_remove(b2.data_json, '$.forms['||j.key||'].form_tier'),                  '$.forms['||j.key||'].bab', 'GT:form_family:bab_nasara')  FROM ar_ling_lexicon_block b2, json_each(json_extract(b2.data_json,'$.forms')) j  WHERE b2.id = ar_ling_lexicon_block.id AND json_extract(j.value,'$.section_id') = 'sec_lane_a11dec5ba48c7f0b') WHERE id LIKE 'blk_lane_fam_%' AND block_type='sarf_family'   AND EXISTS (SELECT 1 FROM json_each(json_extract(data_json,'$.forms')) j2               WHERE json_extract(j2.value,'$.section_id') = 'sec_lane_a11dec5ba48c7f0b'                 AND json_extract(j2.value,'$.bab') IS NULL);
